"""Per-file dispatch. ``analyze_entry`` never raises; failures are recorded on the result."""

from __future__ import annotations

import re

from .metrics import FileResult
from .other_analyzer import Src, analyze_go, analyze_java, analyze_js
from .py_analyzer import analyze_python
from .scanner import FileEntry

_GENERATED = ("code generated", "do not edit", "@generated", "auto-generated", "autogenerated",
              "automatically generated", "this file is generated")


def analyze_entry(entry: FileEntry, max_bytes: int = 1_000_000) -> FileResult:
    res = FileResult(path=entry.rel_path, language=entry.language, is_test=entry.is_test)
    try:
        with open(entry.abs_path, "rb") as fh:
            data = fh.read(max_bytes + 1)
        if len(data) > max_bytes:
            res.skipped = "too_large"
            return res
        if b"\0" in data[:8192]:
            res.skipped = "binary"
            return res
        text = data.decode("utf-8", errors="replace").lstrip("﻿")
        head = text[:1500].lower()
        if any(g in head for g in _GENERATED):
            res.skipped = "generated"
            return res
        lines = text.count("\n") + 1
        if len(text) > 20_000 and len(text) / lines > 300:
            res.skipped = "minified"
            return res
        if entry.language == "python":
            analyze_python(text, res)
        else:
            src = Src(text, entry.language)
            res.parse_mode = "heuristic"
            res.loc = sum(1 for ln in src.m.split("\n") if ln.strip())
            {"javascript": analyze_js, "typescript": analyze_js,
             "java": analyze_java, "go": analyze_go}[entry.language](src, res)
    except OSError as exc:
        res.skipped = "unreadable"
        res.error = str(exc)
    except (RecursionError, MemoryError) as exc:
        res.parse_mode = "failed"
        res.error = type(exc).__name__
    except Exception as exc:  # noqa: BLE001 - one bad file must not stop the run
        res.parse_mode = "failed"
        res.error = f"{type(exc).__name__}: {exc}"
    return res
